"""Time-value-of-money toolkit."""


def pv_annuity(pmt, rate, n):
    """Present value of an ordinary annuity of `pmt` for `n` periods at `rate`."""
    if rate == 0:
        return pmt * n
    return pmt * (1.0 - (1.0 + rate) ** (-n)) / rate


def fv_annuity(pmt, rate, n):
    """Future value of an ordinary annuity of `pmt` for `n` periods at `rate`."""
    if rate == 0:
        return pmt * n
    return pmt * ((1.0 + rate) ** n - 1.0) / rate


def pv_perpetuity(pmt, rate):
    """Present value of a level perpetuity."""
    return pmt / rate


def pv_growing_perpetuity(pmt, rate, growth):
    """Present value of a perpetuity growing at `growth` per period.

    Raises ValueError when growth >= rate (value is undefined/infinite).
    """
    if growth >= rate:
        raise ValueError("growth must be strictly less than rate")
    return pmt / (rate - growth)


def gordon_price(dividend_next, r, g):
    """Gordon growth model price: D1 / (r - g)."""
    if g >= r:
        raise ValueError("growth must be strictly less than required return")
    return dividend_next / (r - g)

