import pytest
from hypothesis import given, settings
from hypothesis import strategies as st

from tvm import fv_annuity, gordon_price, pv_annuity, pv_growing_perpetuity, pv_perpetuity


# ---------------- inline vectors ----------------

def test_pv_annuity_vector():
    assert pv_annuity(100, 0.05, 10) == pytest.approx(772.1735, abs=1e-4)


def test_pv_perpetuity_exact():
    assert pv_perpetuity(50, 0.04) == 1250


def test_gordon_price_exact():
    assert gordon_price(2.00, 0.08, 0.03) == pytest.approx(40.00)


def test_pv_growing_perpetuity_raises():
    with pytest.raises(ValueError):
        pv_growing_perpetuity(10, 0.06, 0.06)


def test_fv_annuity_consistency():
    # fv = pv discounted forward: pv_annuity * (1+r)^n == fv_annuity
    pmt, r, n = 100.0, 0.05, 10
    assert fv_annuity(pmt, r, n) == pytest.approx(pv_annuity(pmt, r, n) * (1 + r) ** n)


# ---------------- property tests ----------------

positive_rates = st.floats(min_value=0.001, max_value=0.2)
payments = st.floats(min_value=0.01, max_value=10_000.0)


@settings(max_examples=100, deadline=None)
@given(
    pmt=payments,
    rate=st.floats(min_value=1e-6, max_value=0.01),
    n=st.just(2000),
)
def test_pv_annuity_converges_to_pv_perpetuity(pmt, rate, n):
    pv_n = pv_annuity(pmt, rate, n)
    pv_inf = pv_perpetuity(pmt, rate)
    # within 0.01% of the perpetuity value
    assert pv_n == pytest.approx(pv_inf, rel=1e-4)


@settings(max_examples=100, deadline=None)
@given(
    pmt=payments,
    rate_lo=positive_rates,
    delta=st.floats(min_value=0.001, max_value=0.1),
    n=st.integers(min_value=1, max_value=500),
)
def test_pv_decreasing_in_rate(pmt, rate_lo, delta, n):
    pv_low = pv_annuity(pmt, rate_lo, n)
    pv_high = pv_annuity(pmt, rate_lo + delta, n)
    # higher discount rate -> lower present value
    assert pv_high < pv_low


@settings(max_examples=50, deadline=None)
@given(
    pmt=payments,
    rate=st.floats(min_value=0.02, max_value=0.3),
    growth=st.floats(min_value=-0.05, max_value=0.25),
)
def test_gordon_matches_growing_perpetuity(pmt, rate, growth):
    if growth >= rate:
        with pytest.raises(ValueError):
            gordon_price(pmt, rate, growth)
        with pytest.raises(ValueError):
            pv_growing_perpetuity(pmt, rate, growth)
    else:
        assert gordon_price(pmt, rate, growth) == pytest.approx(
            pv_growing_perpetuity(pmt, rate, growth), rel=1e-12
        )

